# >>> STATIC
_static_config_domain() {
    cat <<-'ARGCEOF'
	system	When given the "system" argument, modifies the configuration for the system domain
	user	When given the "user" argument on supported platforms, modifies the configuration for all user domains
ARGCEOF
}

_static_config_parameter() {
    cat <<-'ARGCEOF'
	umask	Modifies the umask(2) applied to services launched in the domain
	path	Modifies the PATH environment variable set on each service in the domain
ARGCEOF
}

_static_load_D() {
    cat <<-'ARGCEOF'
	system	Searches /System/Library for either daemons or agents
	local	Searches /Library for either daemons or agents
	network	Searches /Network
	user	Searches the home directory of the calling user for agents only
ARGCEOF
}
