_choice_launchctl_label() {
    launchctl list 2>/dev/null | gawk 'NR > 1 && NF >= 3 && n < 500 { print $3; n++ }'
}

_choice_limit_name() {
    launchctl limit 2>/dev/null | gawk 'NF >= 3 { print $1 }'
}

_choice_signal() {
    builtin kill -l 2>/dev/null | gawk '{ for (i = 1; i <= NF; i++) if ($i ~ /^SIG/) print $i }'
}
